(()=>{
function refreshDataEmpty(){document.querySelectorAll('#data-tab section').forEach(section=>{const wrap=section.querySelector('.data-table-scroll'),empty=section.querySelector('.data-empty');if(!wrap||!empty)return;const count=[...wrap.querySelectorAll('tbody tr')].filter(row=>!row.hidden&&!row.classList.contains('data-group-header')).length;wrap.hidden=count===0;empty.hidden=count!==0})}
function styleData(){const tab=document.querySelector('#data-tab');if(!tab||tab.dataset.dataStyled)return;tab.dataset.dataStyled='true';tab.querySelectorAll('section').forEach(section=>{const table=section.querySelector('table');if(!table)return;const scroll=document.createElement('div');scroll.className='data-table-scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label',section.querySelector('.section-title').textContent+'明细，可横向滚动');table.before(scroll);scroll.append(table);table.querySelectorAll('tbody tr').forEach(row=>{if(row.cells.length===1&&row.cells[0].colSpan>1){row.classList.add('data-group-header');row.querySelector('.note')?.classList.add('data-impact-critical')}else{const action=row.cells[row.cells.length-1];if(!action.querySelector('button'))action.classList.add('data-source-action')}});const empty=document.createElement('div');empty.className='data-empty';empty.textContent=section.id==='confirmations'?'当前筛选范围内暂无待人工确认事项':'当前筛选范围内暂无字段缺失或配置错误';empty.hidden=true;empty.setAttribute('role','status');section.append(empty)});refreshDataEmpty()}
const previousRender=render;render=function(){previousRender();styleData()};const previousFilters=applyFilters;applyFilters=function(){previousFilters();refreshDataEmpty()};styleData();
if(new URLSearchParams(location.search).get('actionTab')==='data'){state.actionTab='data';setActionTab('data')}
})();

